import { Document, PageFormat } from "@asposefoss/pdf";

function main(): void {
  const doc = Document.New(PageFormat.A4);
  const page = doc.Pages[0];

  page.AddTextField({ rect: [100, 700, 350, 720], name: "FullName", value: "Alice Sample" });
  page.AddCheckbox({ rect: [100, 670, 118, 688], name: "Subscribe", checked: true });

  const path = "outputfiles/cand2.pdf";
  doc.WriteTo(path);

  const reloaded = Document.OpenFile(path);
  const form = reloaded.Form;
  const nameField = form.Get("FullName");
  const subscribeField = form.Get("Subscribe");
  if (!nameField) throw new Error("expected FullName field to survive the reload");
  if (!subscribeField) throw new Error("expected Subscribe field to survive the reload");

  console.log("name field value:", nameField.Value, "subscribe field value:", subscribeField.Value);

  if (nameField.Value !== "Alice Sample") throw new Error(`expected name value Alice Sample, got ${nameField.Value}`);
  if (subscribeField.Value !== true) throw new Error(`expected subscribe checkbox to be checked, got ${subscribeField.Value}`);
  console.log("cand2 OK");
}

main();
