Kind: verified_example
Provenance: authored
Verification: passed
Authored example: written for foss-mcp against the pinned library, not taken from the upstream README; published only after the ingestion verifier compiled or ran it against that commit.
Generates a MatrixBarcode with makeQr and a LinearBarcode with makeCode128, checks the real module counts and dark/light mix of the QR matrix and the stored payload of the Code128 symbol, then places the QR on a page with Page.AddBarcode and confirms the document still saves and reloads with one page.

Example:
// Authored example: generate a QR matrix barcode and a Code128 linear barcode, place the QR on a page, and check their real geometry.
import { Document, PageFormat, makeQr, makeCode128 } from "@asposefoss/pdf";

function main(): void {
  const qr = makeQr("https://example.com/invoice/42");
  const code128 = makeCode128("INVOICE-0042");

  console.log("qr size:", qr.size, "dark modules:", qr.dark.filter(Boolean).length);
  console.log("code128 module count:", code128.modules.length);

  if (qr.kind !== "matrix") throw new Error(`expected a matrix barcode, got ${qr.kind}`);
  if (qr.size <= 0) throw new Error(`expected a positive QR size, got ${qr.size}`);
  if (qr.dark.length !== qr.size * qr.size) throw new Error(`expected ${qr.size * qr.size} modules, got ${qr.dark.length}`);
  const darkCount = qr.dark.filter(Boolean).length;
  if (darkCount === 0 || darkCount === qr.dark.length) throw new Error(`expected a mix of dark and light QR modules, got ${darkCount} dark of ${qr.dark.length}`);

  if (code128.kind !== "linear") throw new Error(`expected a linear barcode, got ${code128.kind}`);
  if (code128.modules.length === 0) throw new Error("expected code128 to produce at least one module width");
  if (code128.text !== "INVOICE-0042") throw new Error(`expected stored text INVOICE-0042, got ${code128.text}`);

  const doc = Document.New(PageFormat.A4);
  const page = doc.Pages[0];
  page.AddBarcode({ type: "qr", data: "https://example.com/invoice/42" }, [72, 700, 172, 800]);

  const path = "outputfiles/cand5.pdf";
  doc.WriteTo(path);

  const reloaded = Document.OpenFile(path);
  if (reloaded.Pages.length !== 1) throw new Error(`expected 1 page after reload, got ${reloaded.Pages.length}`);
  console.log("cand5 OK");
}

main();
