// Authored example: set a two-level bookmark outline on a document, save and reload, and read the outline back.
import { Document, PageFormat } from "@asposefoss/pdf";

function main(): void {
  const doc = Document.New(PageFormat.A4);
  doc.AddPage(PageFormat.A4);
  doc.AddPage(PageFormat.A4);

  doc.SetOutlines([
    {
      Title: "Chapter 1",
      Dest: { page: 1 },
      Children: [{ Title: "Section 1.1", Dest: { page: 2 } }],
    },
    { Title: "Chapter 2", Dest: { page: 3 } },
  ]);

  const path = "outputfiles/cand4.pdf";
  doc.WriteTo(path);

  const reloaded = Document.OpenFile(path);
  const outlines = reloaded.GetOutlines();
  console.log("outline titles:", outlines.map((item) => item.Title));

