  if (outlines[1].Title !== "Chapter 2") throw new Error(`expected second title Chapter 2, got ${outlines[1].Title}`);
  const children = outlines[0].Children ?? [];
  if (children.length !== 1 || children[0].Title !== "Section 1.1") {
    throw new Error(`expected one child titled Section 1.1, got ${JSON.stringify(children)}`);
  }
  const firstDest = outlines[0].Dest;
  if (!firstDest || !("page" in firstDest) || firstDest.page !== 1) {
    throw new Error(`expected Chapter 1 to point at page 1, got ${JSON.stringify(firstDest)}`);
  }
  console.log("cand4 OK");
}

