  const note = annotations.find((a) => a instanceof TextAnnotation);
  const highlight = annotations.find((a) => a instanceof MarkupAnnotation);
  if (!note) throw new Error("expected a TextAnnotation (sticky note) after reload");
  if (!highlight) throw new Error("expected a MarkupAnnotation (highlight) after reload");

  if (note.Contents !== "Check these numbers") throw new Error(`unexpected note contents: ${note.Contents}`);
  if (highlight.Contents !== "important total") throw new Error(`unexpected highlight contents: ${highlight.Contents}`);
