  if (code128.text !== "INVOICE-0042") throw new Error(`expected stored text INVOICE-0042, got ${code128.text}`);

  const doc = Document.New(PageFormat.A4);
  const page = doc.Pages[0];
  page.AddBarcode({ type: "qr", data: "https://example.com/invoice/42" }, [72, 700, 172, 800]);

  const path = "outputfiles/cand5.pdf";
  doc.WriteTo(path);

  const reloaded = Document.OpenFile(path);
  if (reloaded.Pages.length !== 1) throw new Error(`expected 1 page after reload, got ${reloaded.Pages.length}`);
  console.log("cand5 OK");
}

main();
